impl officekit_markup_base::Read for ControlPropertiesContent {
    fn other(node: Node) -> Option<Self> {
        Some(Self::Other(node))
    }

    fn read(element: &Element) -> Self {
        match officekit_markup_base::name(element) {
            Some((NS_W, "del")) => {
                Self::DeletedMathControlCharacter(officekit_markup_base::read(element))
            }
            Some((NS_W, "ins")) => {
                Self::InsertedMathControlCharacter(officekit_markup_base::read(element))
            }
            Some((NS_W, "rPr")) => Self::RunProperties(officekit_markup_base::read(element)),
            _ => Self::Other(Node::Element(element.clone())),
        }
    }
}

impl officekit_markup_base::Write for ControlPropertiesContent {
    fn write_into(&self, writer: &mut officekit_markup_base::Writer<'_, '_>) {
        match self {
            Self::DeletedMathControlCharacter(arm) => arm.write_into(writer),
            Self::InsertedMathControlCharacter(arm) => arm.write_into(writer),
            Self::Other(node) => writer.other(node.clone()),
            Self::RunProperties(arm) => arm.write_into(writer),
        }
    }
}

